ST.xhtml:
{region "§1 Gate + fronts + machine d'etat"}
ReqEdge(CLK := Request);
ResetEdge(CLK := Reset);

IF NOT Enable THEN
    Step := 0;
    RestartPulse := FALSE;
    InvalidateEncoders := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    Ready := FALSE;
    TonPowerUp(IN := FALSE);
    TonConfig(IN := FALSE);
ELSE
    Ready := TRUE;
    RestartPulse := FALSE;      // impulsion : FALSE par defaut, TRUE 1 cycle en step PULSE
    InvalidateEncoders := FALSE;

    // CASE a etiquettes litterales : 0..6 (voir declaration Step).
    CASE Step OF
        0: // IDLE
            Lifecycle.Busy := FALSE;
            TonPowerUp(IN := FALSE);
            TonConfig(IN := FALSE);
            IF ReqEdge.Q AND BusInError THEN
                IF MachineStopped THEN
                    CauseNotStopped    := FALSE;
                    CauseConfigTimeout := FALSE;
                    CauseMasterError   := FALSE;
                    CauseBusStillDown  := FALSE;
                    Lifecycle.Done := FALSE;
                    Step := 1;
                ELSE
                    CauseNotStopped := TRUE; // refus : machine pas a l'arret
                END_IF;
            END_IF;

        1: // WAIT_POWERUP
            Lifecycle.Busy := TRUE;
            TonPowerUp(IN := TRUE, PT := Cfg_PowerUpDelay);
            IF NOT MachineStopped THEN
                CauseNotStopped := TRUE;
                Step := 6;
            ELSIF TonPowerUp.Q THEN
                Step := 2;
            END_IF;

        2: // PULSE
            RestartPulse := TRUE; // 1 cycle -> EtherCAT_Master.xRestart
            Step := 3;

        3: // WAIT_CONFIG
            TonConfig(IN := TRUE, PT := Cfg_ConfigTimeout);
            IF MasterError THEN
                CauseMasterError := TRUE;
                Step := 6;
            ELSIF MasterConfigFinished AND NOT BusInError THEN
                Step := 4;
            ELSIF TonConfig.Q THEN
                IF BusInError THEN
                    CauseBusStillDown := TRUE;
                ELSE
                    CauseConfigTimeout := TRUE;
                END_IF;
                Step := 6;
            END_IF;

        4: // SETTLE
            InvalidateEncoders := TRUE; // 1 cycle -> re-homing obligatoire M1/M2
            Step := 5;

        5: // DONE
            Lifecycle.Busy := FALSE;
            Lifecycle.Done := TRUE;
            IF ReqEdge.Q THEN
                Step := 0; // re-armable
            END_IF;

        6: // FAIL
            Lifecycle.Busy := FALSE;
            IF ResetEdge.Q THEN
                Step := 0;
            END_IF;

        ELSE
            Step := 0;
    END_CASE;
END_IF;
{endregion}

{region "§2 Socle defaut (FB_FaultCore)"}
instCauses[0].Active := CauseNotStopped;    instCauses[0].Latching := TRUE; instCauses[0].Texte := 'Recovery EtherCAT refuse - machine non arretee';
instCauses[1].Active := CauseConfigTimeout; instCauses[1].Latching := TRUE; instCauses[1].Texte := 'Recovery EtherCAT - xConfigFinished timeout';
instCauses[2].Active := CauseMasterError;   instCauses[2].Latching := TRUE; instCauses[2].Texte := 'Recovery EtherCAT - maitre en erreur';
instCauses[3].Active := CauseBusStillDown;  instCauses[3].Latching := TRUE; instCauses[3].Texte := 'Recovery EtherCAT - esclaves hors RUNNING';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}
